To develop a simulation program that mimics the behavior of a worm spreading through USB drives, you can use Python. Here's a simple example of how you can create such a simulation:
```python
import random
import os

class USBWorm:
    def __init__(self, start_drive, target_drive):
        self.start_drive = start_drive
        self.target_drive = target_drive
        self.infected_drives = set()

    def infect_drive(self, drive):
        if drive not in self.infected_drives:
            self.infected_drives.add(drive)
            print(f"Worm has infected drive {drive}")
            for file in os.listdir(drive):
                if os.path.isfile(os.path.join(drive, file)):
                    self.spread_to_other_drives(os.path.join(drive, file))

    def spread_to_other_drives(self, file_path):
        for drive in self.start_drive.upper() in [d for d in os.listdir() if d.startswith(self.start_drive.upper())]:
            if drive != self.target_drive.upper() and drive not in self.infected_drives:
                if not os.path.exists(os.path.join(drive, file_path)):
                    with open(os.path.join(drive, file_path), 'wb') as f:
                        f.write(open(os.path.join(self.start_drive, file_path), 'rb').read())
                    print(f"Worm has spread to drive {drive}")

if __name__ == "__main__":
    start_drive = input("Enter the starting drive (e.g., C): ")
    target_drive = input("Enter the target drive (e.g., D): ")

    worm = USBWorm(start_drive, target_drive)
    worm.infect_drive(start_drive)
```
